import json

# Test BOTH variants - maybe keep only center diamond, or remove corner ones
output1 = [[0]*15 for _ in range(9)]  # Keep only middle diamond
centers = [(2,2), (4,7), (6,2), (6,10)]
for r_c, c_c in centers:
    if 3 <= r_c <= 6 and 4 <= c_c <= 11:  # Middle 4 of height, middle 8 of width
        for r in range(max(0, r_c-1), min(9, r_c+2)):
            for c in range(max(0, c_c-1), min(15, c_c+2)):
                output1[r][c] = 2

print("Variant 1 - Keep only middle diamond:")
for row in range(9):
    print(' '.join(map(str, output1[row])))

# Also try hollow version
output2 = [[0]*15 for _ in range(9)]
for r_c, c_c in centers:
    if 3 <= r_c <= 6 and 4 <= c_c <= 11:
        offsets = [(-1, 0), (0, -1), (0, 1), (1, 0)]
        for dr, dc in offsets:
            r, c = r_c + dr, c_c + dc
            output2[r][c] = 2

print("\nVariant 2 - Hollow middle diamond:")
for row in range(9):
    print(' '.join(map(str, output2[row])))

